public class InstructionMaskValueFieldFactory : FieldFactory {

	public static readonly string FIELD_NAME = "Instr Mask/Value";

	/**
	 * Default constructor.
	 */
	public InstructionMaskValueFieldFactory() : base(FIELD_NAME)
    {
	}

	/**
	 * Constructor
	 * @param model the model that the field belongs to.
	 * @param hsProvider the HightLightStringProvider.
	 * @param displayOptions the Options for display properties.
	 * @param fieldOptions the Options for field specific properties.
	 */
	private InstructionMaskValueFieldFactory(FieldFormatModel model,
			ListingHighlightProvider hsProvider,
			Options displayOptions, Options fieldOptions) : base(FIELD_NAME, model, hsProvider, displayOptions, fieldOptions)
    {
	}

	/**
	 * Returns the FactoryField for the given object at index index.
	 * @param varWidth the amount of variable width spacing for any fields
	 * before this one.
	 * @param proxy the object whose properties should be displayed.
	 */
	/* @Override */
	public ListingField getField(ProxyObj<object> proxy, int varWidth) {
		object obj = proxy.getObject();

		if (!enabled || !(obj is Instruction)) {
			return null;
		}
		Instruction instr = (Instruction) obj;
		InstructionPrototype proto = instr.getPrototype();
		int operandCount = proto.getNumOperands();
		Mask instructionMask = proto.getInstructionMask();
		if (instructionMask == null) {
			return null;
		}
		Mask[] operandMasks = new Mask[operandCount];
		for (int i = 0; i < operandCount; i++) {
			operandMasks[i] = proto.getOperandValueMask(i);
			if (operandMasks[i] == null) {
				// disable operand mask display
				operandCount = 0;
				break;
			}
		}

		try {
			List<FieldElement> elements = new();
			elements.add(
				getLine("M[m]: ", instructionMask.getBytes(), MaskColors.BITS, proxy, varWidth));
			elements.add(getLine("V[m]: ", instructionMask.applyMask(instr), MaskColors.VALUE,
				proxy, varWidth));

			for (int i = 0; i < operandCount; i++) {
				elements.add(getLine("M[" + i + "]: ", operandMasks[i].getBytes(), MaskColors.BITS,
					proxy, varWidth));
				elements.add(getLine("V[" + i + "]: ", operandMasks[i].applyMask(instr),
					MaskColors.VALUE, proxy, varWidth));
			}

			return ListingTextField.createMultilineTextField(this, proxy, elements,
				startX + varWidth, width, hlProvider);
		}
		catch (MemoryAccessException e) {
			return null;
		}
	}

	private FieldElement getLine(string label, byte[] value, Color valueColor, ProxyObj<object> proxy,
			int varWidth) {

		FieldElement[] fieldElements = new FieldElement[2];
		AttributedString @as =
			new AttributedString(label, MaskColors.LABEL, getMetrics(), false,
				ListingColors.UNDERLINE);
		fieldElements[0] = new TextFieldElement(@as, 0, 0);
		@as = new AttributedString(getFormattedBytes(value), valueColor, getMetrics(), false,
			ListingColors.UNDERLINE);
		fieldElements[1] = new TextFieldElement(@as, 0, 0);
		return new CompositeFieldElement(fieldElements);
	}

	private string getFormattedBytes(byte[] value) {
		StringBuffer buf = new StringBuffer();
		for (int i = 0; i < value.length; i++) {
			string byteStr = StringUtilities.pad(Integer.toBinaryString(value[i] & 0xff), '0', 8);
			buf.append(byteStr);
			if (i < (value.length - 1)) {
				buf.append(".");
			}
		}
		return buf.toString();
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int row, int col, ListingField bf) {
		object obj = bf.getProxy().getObject();
		if (!(obj is Instruction)) {
			return null;
		}
		Instruction instr = (Instruction) obj;

		return new InstructionMaskValueFieldLocation(instr.getProgram(), instr.getMinAddress(), row,
			col);
	}

	/* @Override */
	public FieldLocation getFieldLocation(ListingField bf, BigInteger index, int fieldNum,
			ProgramLocation programLoc) {
		if (programLoc is InstructionMaskValueFieldLocation) {
			InstructionMaskValueFieldLocation maskValueLoc =
				(InstructionMaskValueFieldLocation) programLoc;
			return new FieldLocation(index, fieldNum, maskValueLoc.getRow(),
				maskValueLoc.getCharOffset());
		}
		return null;
	}

	/* @Override */
	public bool acceptsType(int category, Class<object> proxyObjectClass) {
		return category == FieldFormatModel.INSTRUCTION_OR_DATA;
	}

	/* @Override */
	public FieldFactory newInstance(FieldFormatModel formatModel,
			ListingHighlightProvider hsProvider,
			ToolOptions toolOptions, ToolOptions fieldOptions) {
		return new InstructionMaskValueFieldFactory(formatModel, hsProvider, toolOptions,
			fieldOptions);
	}
}
